import threading
from test.support import import_helper
py_queue = import_helper.import_fresh_module('queue', blocked=['_queue'])

def _t():

    def setUp():
        self.type2test = self.queue.Queue
        self.cum = 0
        self.cumlock = threading.Lock()

    class _SelfNS:
        pass
    self = _SelfNS()
    self.queue = py_queue
    _SelfNS.queue = py_queue
    self.type2test = self.queue.Queue
    self.cum = 0
    self.cumlock = threading.Lock()
    q = self.type2test()
    try:
        q.task_done()
    except ValueError:
        pass
    else:
        raise AssertionError('Did not detect task count going negative')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

