import threading
import time
from test.support import import_helper
from test.support import threading_helper
py_queue = import_helper.import_fresh_module('queue', blocked=['_queue'])
QUEUE_SIZE = 5

def qfull(q):
    return q.maxsize > 0 and q.qsize() == q.maxsize

class _TriggerThread(threading.Thread):

    def __init__(self, fn, args):
        self.fn = fn
        self.args = args
        self.startedEvent = threading.Event()
        threading.Thread.__init__(self)

    def run(self):
        time.sleep(0.1)
        self.startedEvent.set()
        self.fn(*self.args)

class FailingQueueException(Exception):
    pass

class _TriggerThread(threading.Thread):

    def __init__(self, fn, args):
        self.fn = fn
        self.args = args
        self.startedEvent = threading.Event()
        threading.Thread.__init__(self)

    def run(self):
        time.sleep(0.1)
        self.startedEvent.set()
        self.fn(*self.args)

class FailingQueueException(Exception):
    pass

def _t():

    def setUp():
        Queue = self.queue.Queue

        class FailingQueue(Queue):

            def __init__(self, *args):
                self.fail_next_put = False
                self.fail_next_get = False
                Queue.__init__(self, *args)

            def _put(self, item):
                if self.fail_next_put:
                    self.fail_next_put = False
                    raise FailingQueueException('You Lose')
                return Queue._put(self, item)

            def _get(self):
                if self.fail_next_get:
                    self.fail_next_get = False
                    raise FailingQueueException('You Lose')
                return Queue._get(self)
        self.FailingQueue = FailingQueue

    def do_blocking_test(block_func, block_args, trigger_func, trigger_args):
        thread = _TriggerThread(trigger_func, trigger_args)
        thread.start()
        try:
            self.result = block_func(*block_args)
            if not thread.startedEvent.is_set():
                raise AssertionError('blocking function %r appeared not to block' % block_func)
            return self.result
        finally:
            threading_helper.join_thread(thread)

    def do_exceptional_blocking_test(block_func, block_args, trigger_func, trigger_args, expected_exception_class):
        thread = _TriggerThread(trigger_func, trigger_args)
        thread.start()
        try:
            try:
                block_func(*block_args)
            except expected_exception_class:
                raise
            else:
                raise AssertionError('expected exception of kind %r' % expected_exception_class)
        finally:
            threading_helper.join_thread(thread)
            if not thread.startedEvent.is_set():
                raise AssertionError('trigger thread ended but event never set')

    def failing_queue_test(q):
        if q.qsize():
            raise RuntimeError('Call this function with an empty queue')
        for i in range(QUEUE_SIZE - 1):
            q.put(i)
        q.fail_next_put = True
        try:
            q.put('oops', block=0)
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        q.fail_next_put = True
        try:
            q.put('oops', timeout=0.1)
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        q.put('last')
        assert qfull(q), ('assertTrue', qfull(q))
        q.fail_next_put = True
        try:
            do_blocking_test(q.put, ('full',), q.get, ())
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        q.put('last')
        q.fail_next_put = True
        try:
            do_exceptional_blocking_test(q.put, ('full', True, 10), q.get, (), FailingQueueException)
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        q.put('last')
        assert qfull(q), ('assertTrue', qfull(q))
        q.get()
        assert not qfull(q), ('assertTrue', not qfull(q))
        q.put('last')
        assert qfull(q), ('assertTrue', qfull(q))
        do_blocking_test(q.put, ('full',), q.get, ())
        for i in range(QUEUE_SIZE):
            q.get()
        assert not q.qsize(), ('assertTrue', not q.qsize())
        q.put('first')
        q.fail_next_get = True
        try:
            q.get()
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        assert q.qsize(), ('assertTrue', q.qsize())
        q.fail_next_get = True
        try:
            q.get(timeout=0.1)
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        assert q.qsize(), ('assertTrue', q.qsize())
        q.get()
        assert not q.qsize(), ('assertTrue', not q.qsize())
        q.fail_next_get = True
        try:
            do_exceptional_blocking_test(q.get, (), q.put, ('empty',), FailingQueueException)
            raise AssertionError("The queue didn't fail when it should have")
        except FailingQueueException:
            pass
        assert q.qsize(), ('assertTrue', q.qsize())
        q.get()
        assert not q.qsize(), ('assertTrue', not q.qsize())

    class _SelfNS:
        pass
    self = _SelfNS()
    self.queue = py_queue
    _SelfNS.queue = py_queue
    Queue = self.queue.Queue

    class FailingQueue(Queue):

        def __init__(self, *args):
            self.fail_next_put = False
            self.fail_next_get = False
            Queue.__init__(self, *args)

        def _put(self, item):
            if self.fail_next_put:
                self.fail_next_put = False
                raise FailingQueueException('You Lose')
            return Queue._put(self, item)

        def _get(self):
            if self.fail_next_get:
                self.fail_next_get = False
                raise FailingQueueException('You Lose')
            return Queue._get(self)
    self.FailingQueue = FailingQueue
    q = self.FailingQueue(QUEUE_SIZE)
    failing_queue_test(q)
    failing_queue_test(q)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

